//! Unit tests of the daemon binary (`main.rs`), split by area.
//!
//! Generated by `crates/stat-tracker/scripts/split-main-tests.py` from the old inline `mod tests`
//! of `main.rs`: shared helpers live here, `pub(crate)` so a test file anywhere in the crate can
//! reach them (`use crate::{main_tests::*, *};`); area files use `use super::*;`.

use super::*;

