/// Key events from a list; then nothing more ever arrives.
pub(crate) struct ScriptedKeys(pub(crate) std::collections::VecDeque<detect::TabKey>);

impl stat_tracker::tab_retry::TabKeySource for ScriptedKeys {
    fn next_key(
        &mut self,
    ) -> impl std::future::Future<Output = Result<detect::TabKey, Box<dyn std::error::Error>>> {
        let key = self.0.pop_front();
        async move {
            match key {
                Some(key) => Ok(key),
                None => std::future::pending().await,
            }
        }
    }
}

pub(crate) async fn slow_poll(done: std::sync::Arc<std::sync::atomic::AtomicBool>) -> &'static str {
    tokio::time::sleep(std::time::Duration::from_secs(30)).await;
    done.store(true, std::sync::atomic::Ordering::SeqCst);
    "read"
}

/// Production poll cadence. A stable screen is emitted on every tick.
pub(crate) const NIGHT_TICKS: usize = 4;

pub(crate) fn night_tick() -> Duration {
    config::AutoDetectConfig::default().poll_interval(false)
}

pub(crate) fn night_debounce() -> Duration {
    Duration::from_secs(config::AutoDetectConfig::default().cooldown_secs)
}

pub(crate) fn night_counters(e: u32, a: u32, d: u32, dmg: u32, hlg: u32, mit: u32) -> Counters {
    Counters {
        elims: e,
        assists: a,
        deaths: d,
        damage: dmg,
        healing: hlg,
        mitigation: mit,
    }
}

pub(crate) const NIGHT_CLEAN: [bool; stat_tracker::capture_gate::GATE_COLS] =
    [false; stat_tracker::capture_gate::GATE_COLS];

/// Drives the real poll and Tab path at the production cadence, with the
/// gap, grace, debounce, and idle bounds left on. Time is the injected clock.
pub(crate) struct Night {
    pub(crate) st: SessionState,
    pub(crate) store: storage::LocalStore,
    pub(crate) dir: tempfile::TempDir,
    pub(crate) now: Instant,
    pub(crate) wall: chrono::DateTime<Utc>,
    pub(crate) syncs: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    pub(crate) uploads: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    /// Overrides the "a row index means per-cell stats" bit for the next
    /// Tab. `None` keeps that bit. `Some(false)` is an identified row
    /// whose cells were unreadable, so the text fallback was used.
    pub(crate) cells_trusted: Option<bool>,
    /// The next Tab's top-bar label is a sure banner read (`reader = "new"`), not the top-bar OCR.
    pub(crate) panel_from_banner: bool,
}

impl Night {
    pub(crate) async fn new() -> Self {
        let dir = tempfile::tempdir().unwrap();
        let store = storage::LocalStore::open(dir.path()).await.unwrap();
        let now = test_now();
        Self {
            st: session(None, now),
            store,
            dir,
            now,
            wall: Utc::now(),
            syncs: std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0)),
            uploads: std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0)),
            cells_trusted: None,
            panel_from_banner: false,
        }
    }

    pub(crate) fn sync_count(&self) -> usize {
        self.syncs.load(std::sync::atomic::Ordering::SeqCst)
    }

    pub(crate) fn upload_count(&self) -> usize {
        self.uploads.load(std::sync::atomic::Ordering::SeqCst)
    }

    /// One command tick of the quiet-session timer. Same function the daemon loop calls. The
    /// closure schedules the upload. It is not the shutdown upload.
    pub(crate) async fn quiet_tick(&mut self) -> bool {
        let syncs = std::sync::Arc::clone(&self.syncs);
        let uploads = std::sync::Arc::clone(&self.uploads);
        let store = self.store.clone();
        let dir = self.dir.path().to_path_buf();
        close_quiet_session_and_sync(
            &mut self.st,
            &self.store,
            self.dir.path(),
            self.now,
            finished_game_close_after(config::FINISHED_GAME_CLOSE_DEFAULT_SECS),
            || {
                let syncs = std::sync::Arc::clone(&syncs);
                let uploads = std::sync::Arc::clone(&uploads);
                let store = store.clone();
                let dir = dir.clone();
                async move {
                    syncs.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    let _ = try_sync_with(&store, &dir, None, move |_matches, _tombstones| {
                        let uploads = std::sync::Arc::clone(&uploads);
                        async move {
                            uploads.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                            Ok(upload_ok())
                        }
                    })
                    .await;
                }
            },
        )
        .await
    }

    /// Step the injected clock the way the 3-second command tick does,
    /// and run the quiet-close timer on each step.
    pub(crate) async fn idle_through(&mut self, until: Instant) {
        while self.now < until {
            let step = until
                .saturating_duration_since(self.now)
                .min(Duration::from_secs(3));
            if step.is_zero() {
                break;
            }
            self.advance(step);
            self.quiet_tick().await;
        }
    }

    /// What a daemon restart does with the on-disk skeleton.
    pub(crate) async fn restart_from_disk(&self) -> Option<ActiveGame> {
        let syncs = std::sync::Arc::clone(&self.syncs);
        let uploads = std::sync::Arc::clone(&self.uploads);
        let store = self.store.clone();
        let dir = self.dir.path().to_path_buf();
        recover_or_sync_active_game(self.dir.path(), &self.store, |dropped| {
            let syncs = std::sync::Arc::clone(&syncs);
            let uploads = std::sync::Arc::clone(&uploads);
            let store = store.clone();
            let dir = dir.clone();
            async move {
                syncs.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                let _ = try_sync_with(&store, &dir, dropped, move |_matches, _tombstones| {
                    let uploads = std::sync::Arc::clone(&uploads);
                    async move {
                        uploads.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                        Ok(upload_ok())
                    }
                })
                .await;
            }
        })
        .await
        .active_game
    }

    pub(crate) fn advance(&mut self, by: Duration) {
        self.now += by;
        self.wall += chrono::Duration::from_std(by).unwrap();
    }

    pub(crate) fn game(&self) -> &ActiveGame {
        self.st.active_game.as_ref().expect("active game")
    }

    pub(crate) fn id(&self) -> String {
        self.game().session_id.clone()
    }

    /// A match already underway, the way a recovered session looks.
    pub(crate) fn begin_on(&mut self, map: &str, hero: &str) {
        let mut g = ActiveGame::open_at(
            format!("{:016x}", rand_id()),
            detect::MatchOutcome::Unknown,
            Vec::new(),
            self.now,
        );
        g.map = Some(map.to_string());
        g.map_source = Some(boundary::MapSource::TopBar);
        g.hero_auth.accepted_hero = Some(hero.to_string());
        self.st.active_game = Some(g);
        self.st.last_game_open = Some(self.now);
    }

    pub(crate) async fn poll_screen(&mut self, screen: boundary::StartScreen) {
        self.apply_resolved_tick(
            ResolvedWordTick {
                signal: None,
                signal_confirmed: false,
                accolade_map: None,
            },
            Some(screen),
        )
        .await;
    }

    /// Apply one resolved poll tick through [`apply_poll_tick`], the same function [`run_loop`]
    /// calls. [`resolve_word_tick`] has already noted the streak. When no game is open, this
    /// records a confirmed word as the pending outcome.
    pub(crate) async fn apply_resolved_tick(
        &mut self,
        tick: ResolvedWordTick,
        start_screen: Option<boundary::StartScreen>,
    ) {
        apply_poll_tick(
            &mut self.st,
            &self.store,
            self.dir.path(),
            &tick,
            start_screen,
            self.now,
            night_debounce(),
            // the member-edit rule of `reader = "new"`, as on the Tab path
            true,
        )
        .await;
    }

    /// Several consecutive ticks of one stable screen.
    pub(crate) async fn screen(&mut self, screen: boundary::StartScreen) {
        for i in 0..NIGHT_TICKS {
            self.poll_screen(screen.clone()).await;
            if i + 1 != NIGHT_TICKS {
                self.advance(night_tick());
            }
        }
    }

    /// One result-word tick through [`resolve_word_tick`], including
    /// when no game is open. Production notes that streak too.
    pub(crate) async fn word_tick(&mut self, outcome: detect::MatchOutcome, map: Option<&str>) {
        let tick = resolve_word_tick(
            &mut self.st.word_outcome_streak,
            Some((outcome, detect::match_end::OutcomeSource::ResultWord)),
            self.now,
            map.map(str::to_string),
        );
        self.apply_resolved_tick(tick, None).await;
    }

    /// A result word held across several ticks. The second agreeing tick confirms.
    pub(crate) async fn word(&mut self, outcome: detect::MatchOutcome, map: Option<&str>) {
        for i in 0..NIGHT_TICKS {
            self.word_tick(outcome, map).await;
            if i + 1 != NIGHT_TICKS {
                self.advance(night_tick());
            }
        }
    }

    /// A poll tick with no result word and no start screen.
    pub(crate) async fn no_signal_tick(&mut self) {
        self.apply_resolved_tick(
            ResolvedWordTick {
                signal: None,
                signal_confirmed: false,
                accolade_map: None,
            },
            None,
        )
        .await;
    }

    /// One unconfirmed read. Production has not seen the agreeing tick yet.
    pub(crate) async fn word_once(&mut self, outcome: detect::MatchOutcome) {
        self.word_tick(outcome, None).await;
    }

    /// A result confirmed on this tick with no accolade map: the second agreeing end-title or
    /// rank-screen read, whose first read the test does not need. Production reads the map crop
    /// only on result-word ticks.
    pub(crate) async fn confirmed_without_map(&mut self, outcome: detect::MatchOutcome) {
        let tick = ResolvedWordTick {
            signal: Some(outcome),
            signal_confirmed: true,
            accolade_map: None,
        };
        self.apply_resolved_tick(tick, None).await;
    }

    pub(crate) async fn tab_once(
        &mut self,
        cur: Counters,
        hero: &str,
        row: Option<u32>,
        map: Option<&str>,
        suspect: [bool; stat_tracker::capture_gate::GATE_COLS],
    ) {
        self.tab_read(
            cur,
            hero,
            row,
            (map, map.unwrap_or("")),
            suspect,
            detect::MatchOutcome::Unknown,
        )
        .await;
    }

    /// The top-bar label is a sure banner read (`reader = "new"`).
    pub(crate) async fn tab_banner(
        &mut self,
        cur: Counters,
        hero: &str,
        row: Option<u32>,
        map: &str,
    ) {
        self.panel_from_banner = true;
        self.tab_once(cur, hero, row, Some(map), NIGHT_CLEAN).await;
    }

    /// The map came from full-board text. There is no top-bar label.
    pub(crate) async fn tab_text(
        &mut self,
        cur: Counters,
        hero: &str,
        row: Option<u32>,
        text_map: &str,
        suspect: [bool; stat_tracker::capture_gate::GATE_COLS],
    ) {
        self.tab_read(
            cur,
            hero,
            row,
            (None, text_map),
            suspect,
            detect::MatchOutcome::Unknown,
        )
        .await;
    }

    /// One Tab through the production request, plan, [`stage_capture`], and report.
    /// `maps` is the top-bar label and the full-board fallback. `frame` is
    /// the header on this board. Unknown is a board with none.
    pub(crate) async fn tab_read(
        &mut self,
        cur: Counters,
        hero: &str,
        row: Option<u32>,
        maps: (Option<&str>, &str),
        suspect: [bool; stat_tracker::capture_gate::GATE_COLS],
        frame: detect::MatchOutcome,
    ) {
        let req = self.tab_request().await;
        self.tab_land(req, cur, hero, row, maps, suspect, frame)
            .await;
    }

    /// The Tab press: the session choice and the request the capture task gets. State changes after
    /// this (a poll, a GUI edit) happen while the capture runs; [`Self::tab_land`] is its result.
    pub(crate) async fn tab_request(&mut self) -> CaptureRequest {
        let opened =
            open_fresh_if_tab_starts_one(&mut self.st, &self.store, self.dir.path(), self.now)
                .await;
        let mut req = build_capture_request(self.game(), opened, self.now);
        req.member_map_edit = session_has_member_map_edit(&self.store, &req).await;
        req
    }

    /// The capture task for `req`: plan, store writes and report.
    #[allow(clippy::too_many_arguments)]
    pub(crate) async fn tab_land(
        &mut self,
        req: CaptureRequest,
        cur: Counters,
        hero: &str,
        row: Option<u32>,
        maps: (Option<&str>, &str),
        suspect: [bool; stat_tracker::capture_gate::GATE_COLS],
        frame: detect::MatchOutcome,
    ) {
        let (panel, text_map) = maps;
        let (hero_resolved, source, hero_auth) = hero_auth::resolve_hero(
            Some(hero),
            None,
            hero,
            &req.hero_auth,
            parse::canonical_hero,
        );
        let career_panel = matches!(source, HeroSource::CareerPanel);
        let cells_trusted = self.cells_trusted.take().unwrap_or(row.is_some());
        let mut facts = BoardFacts {
            counters: cur,
            suspect,
            trusted_cells: cells_trusted,
            held: [false; capture_gate::GATE_COLS],
            suspect_row: false,
            row_id: row,
            hero: &hero_resolved,
            map_from_panel: panel,
            panel_from_banner: std::mem::take(&mut self.panel_from_banner),
            parsed_map: text_map,
            frame_outcome: frame,
        };
        let rejoin = rejoin_board(&req, &facts);
        note_rejoin(&req, &rejoin, cur);
        facts.counters = rejoin.counters;
        let plan = plan_from_board(&req, &facts);
        let sid = req.session_id.clone();
        if plan.skip_store {
            let report = skipped_capture_report(
                &plan,
                &sid,
                career_panel,
                hero_auth,
                plan.defer.then(|| hero_resolved.clone()),
                plan.defer.then_some(self.wall),
            );
            apply_capture_report(
                &mut self.st,
                &self.store,
                self.dir.path(),
                &sid,
                Ok(report),
                self.now,
            )
            .await;
            return;
        }
        let mut staged = stage_capture(&req, &plan, &facts, self.wall);
        let mut parsed = test_match(&staged.target_session, &staged.outcome_label);
        if prepare_capture_row(
            &mut parsed,
            &mut staged,
            req.session_map.as_deref(),
            panel,
            text_map,
            true,
        ) == PreparedRow::Drop
        {
            let report = CaptureReport {
                best_guess: None,
                recorded: false,
                outcome: staged.outcome,
                map: None,
                map_source: None,
                session_id: sid.clone(),
                split: false,
                armed_reset: false,
                ignore_row: false,
                reset_streak: plan.reset_streak,
                reset_baseline: plan.reset_baseline,
                baseline_row: plan.baseline_row,
                refresh_baseline: false,
                clear_hint: false,
                count_progress: false,
                career_panel,
                held_counters: None,
                held_hero: None,
                gate_state: None,
                hero_auth,
                seal: None,
                close_reason: None,
                held_at: None,
                map_replaces_text_fallback: false,
                rejoin_carry: None,
                finished_game_tab: None,
            };
            apply_capture_report(
                &mut self.st,
                &self.store,
                self.dir.path(),
                &sid,
                Ok(report),
                self.now,
            )
            .await;
            return;
        }
        write_staged_rows(
            &self.store,
            &staged,
            &hero_resolved,
            "",
            SurrealDatetime::from(self.wall),
        )
        .await
        .unwrap();
        self.write_board(
            &staged.target_session,
            &hero_resolved,
            &staged.map_name,
            &staged.outcome_label,
            staged.gate.accepted,
            self.wall,
        )
        .await;
        write_carried_after_current(&self.store, self.dir.path(), &staged, &hero_resolved, true)
            .await
            .unwrap();
        let report = CaptureReport {
            best_guess: None,
            recorded: true,
            outcome: staged.outcome,
            map: staged.recorded_map,
            map_source: staged.map_source,
            session_id: staged.target_session,
            split: staged.split,
            armed_reset: false,
            ignore_row: plan.ignore_row,
            reset_streak: plan.reset_streak,
            reset_baseline: plan.reset_baseline,
            baseline_row: plan.baseline_row,
            refresh_baseline: plan.refresh_baseline,
            clear_hint: plan.clear_hint,
            count_progress: plan.count_progress,
            career_panel,
            held_counters: None,
            held_hero: None,
            gate_state: Some(staged.gate.state),
            hero_auth,
            seal: plan.seal,
            close_reason: plan.close_reason,
            held_at: None,
            map_replaces_text_fallback: staged.replaced_text_fallback,
            rejoin_carry: rejoin.carry,
            finished_game_tab: None,
        };
        apply_capture_report(
            &mut self.st,
            &self.store,
            self.dir.path(),
            &sid,
            Ok(report),
            self.now,
        )
        .await;
    }

    pub(crate) async fn write_board(
        &self,
        id: &str,
        hero: &str,
        map: &str,
        outcome: &str,
        counters: Counters,
        at: chrono::DateTime<Utc>,
    ) {
        store_held_board(
            &self.store,
            self.dir.path(),
            id,
            hero,
            map,
            outcome,
            counters,
            at,
        )
        .await
        .unwrap();
    }

    /// The same scoreboard captured on several ticks, the way a held Tab is sampled. A fresh board
    /// uses [`Self::tab_once`]: a second sample inside 45 seconds is not a second reset signal.
    pub(crate) async fn tab_held(
        &mut self,
        cur: Counters,
        hero: &str,
        row: Option<u32>,
        map: Option<&str>,
    ) {
        for i in 0..NIGHT_TICKS {
            self.tab_once(cur, hero, row, map, NIGHT_CLEAN).await;
            if i + 1 != NIGHT_TICKS {
                self.advance(night_tick());
            }
        }
    }

    /// A crash and restart: the game goes to disk, a new run restores
    /// it the way startup does, and the rejoin window opens on it.
    pub(crate) async fn crash_and_restart(&mut self) {
        persist_active_game(self.dir.path(), self.st.active_game.as_ref());
        self.st.active_game = None;
        let restored = self.restart_from_disk().await;
        self.now = Instant::now();
        self.wall = Utc::now();
        self.st.active_game = restored;
        self.st.last_game_open = self.st.active_game.as_ref().map(|g| g.opened_at);
        mark_restart_recovered(&mut self.st, self.now);
    }

    pub(crate) async fn elims(&self, session: &str) -> Vec<u32> {
        self.store
            .get_session_snapshots(session)
            .await
            .unwrap()
            .into_iter()
            .map(|row| row.elims)
            .collect()
    }
}

